let angle = 0;
let scale = 0.5;
let luminance = 0.5;

function setup() {
  createCanvas(640, 480, WEBGL);
  noStroke();
}

function draw() {
  background(255);
  translate(width/2, height/2);
  rotateX(rotationX);
  rotateY(rotationY);
  fractalHeart(0, 0, 0.5, 120);
}

function rotationX() {
  return angle;
}

function rotationY() {
  return angle;
}

function fractalHeart(x, y, size, depth) {
  push();
  translate(x, y);
  rotateY(angle);
  rotateX(angle);

  // Base shape
  fill(255, 0, 0, luminance); // Red with some transparency
  box(size, size, size);

  // Recursively generate the fractal shape
  if (depth > 0) {
    fractalHeart(x, y - size/2, size/2, depth-1);
  }

  pop();

  // Update angle and scale for the next iteration
  angle += 0.01;
  scale += 0.001;
  luminance -= 0.001;

  if (luminance < 0) {
    luminance = 0.5;
  }
}
```
