    @Override
    public void transform(ClassTransformer transformer, int classData(),
            JvmtiEnv env, ClassModificationRequest request) {
        // Get the class file bytes
        byte[] classFileBytes = env.getBytecodes(request.getClazz());

        // Create a new class file with the modified method
        byte[] newClassFileBytes = transformClassFile(classFileBytes);

        // Add the new class file to the class loader
        transformer.mutateClassBytes(request.getClazz(), newClassFileBytes);
    }

    private byte[] transformClassFile(byte[] classFileBytes) {
        // Parse the class file
        ClassFile classFile = new ClassFile(classFileBytes);

        // Find all the methods in the class
        for (Method method : classFile.getMethods()) {
            // Log the method call
            Log.d("MethodCall", "Method " + method.getName() + " called");
        }

        // Return the modified class file bytes
        return classFilegetBytes();
    }
}
```
