    const lowercaseChars = 'abcdefghijklmnopqrstuvwxyz';
    const numberChars = '0123456789';
    const specialChars = '!@#$%^&*()_+-={}|[]:<>?,./;\'"';
    const allChars = uppercaseChars + lowercaseChars + numberChars + specialChars;

    for (let i = 0; i < this.minLength; i++) {
      let char;
      if (this.useUppercase && Math.random() < 0.5) {
        char = uppercaseChars.charAt(Math.floor(Math.random() * uppercaseChars.length));
      } else if (this.useLowercase && Math.random() < 0.5) {
        char = lowercaseChars.charAt(Math.floor(Math.random() * lowercaseChars.length));
      } else if (this.useNumbers && Math.random() < 0.33) {
        char = numberChars.charAt(Math.floor(Math.random() * numberChars.length));
      } else {
        char = specialChars.charAt(Math.floor(Math.random() * specialChars.length));
      }
      password.push(char);
    }

    // Shuffle the password to avoid the initial sequence
    for (let i = password.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [password[i], password[j]] = [password[j], password[i]];
    }

    // Shorten the password if it's too long
    if (password.length > this.maxLength) {
      password = password.slice(0, this.maxLength);
    }

    return password.join('');
  }
