```c
#include <windows.h>
#include <iostream>
#include <cmath>
#include <cstdlib>
#include <ctime>

#define N 3 // количество методов интегрирования
#define THREADS 4 // количество потоков
#define TIMES 5 // количество повторов вычислений

// функция для вычисления интеграла методом прямоугольников
double integral_rect(double a, double b, double f(double)) {
    int n = 1000; // количество отрезков
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += h * f(a + i * h);
    }
    return result;
}

// функция для вычисления интеграла методом трапеций
double integraltrap(double a, double b, double f(double)) {
    int n = 1000; // количество отрезков
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        result += 0.5 * h * (f(a + i * h) + f(a + (i + 1) * h));
    }
    return result;
}

// функция для вычисления интеграла методом Симпсона
double integralsimpson(double a, double b, double f(double)) {
    int n = 1000; // количество отрезков
    double h = (b - a) / n;
    double result = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1) {
            result += h * f(a + i * h);
        } else if (i % 2 == 0) {
            result += 2 * h * f(a + i * h);
        } else {
            result += 4 * h * f(a + i * h);
        }
    }
    return result;
}

// функция для запуска потока
DWORD WINAPI thread_func(LPVOID lpParam) {
    int method = *(int*)lpParam; // метод интегрирования
    double a = 0; // нижняя граница отрезка
    double b = 2; // верхняя граница отрезка
    double f(double x) {
        return x * x + 1;
    }

    for (int i = 0; i < TIMES; i++) {
        // добавим случайную задержку
        Sleep(100 + rand() % 500);

        double result = 0;
        switch (method) {
        case 0: // прямоугольники
            result = integral_rect(a, b, f);
            break;
        case 1: // трапеции
            result = integraltrap(a, b, f);
            break;
        case 2: // метод Симпсона
            result = integralsimpson(a, b, f);
            break;
        }

        // синхронизируем вывод с помощью мьютекса
        HANDLE mutex = CreateMutex(NULL, TRUE, NULL);
        WaitForSingleObject(mutex, INFINITE);
        std::cout << "Method: " << method << ", Result: " << result << std::endl;
        ReleaseMutex(mutex);
    }

    return 0;
}

int main() {
    // создаем мьютекс для синхронизации вывода
    HANDLE mutex = CreateMutex(NULL, TRUE, NULL);

    // создаем семафор для ограничения количества потоков
    HANDLE semaphore = CreateSemaphore(NULL, THREADS, THREADS, NULL);

    // создаем массив для хранения потоков
    HANDLE threads[THREADS];
    for (int i = 0; i < THREADS; i++) {
        threads[i] = CreateThread(NULL, 0, thread_func, &i, 0, NULL);
    }

    // ожидаем завершения вычислений всеми потоками
    for (int i = 0; i < THREADS; i++) {
        WaitForSingleObject(threads[i], INFINITE);
    }

    // закрытие потоков и семафора
    for (int i = 0; i < THREADS; i++) {
        CloseHandle(threads[i]);
    }
    CloseHandle(semaphore);
    CloseHandle(mutex);

    return 0;
}
