Here is an example of how you can implement session management using Google OAuth in a React application using classes and Material Design:
```
// auth.js
import React, { Component } from 'react';
import { GoogleAuthProvider, signInWithPopup } from 'react-firebaseui';
import { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut } from 'firebase/auth';
import { Snackbar } from '@material-ui/core';
import { Typography } from '@material-ui/core';

export default class Auth extends Component {
  constructor(props) {
    super(props);
    this.state = {
      user: null,
      error: null,
      signInFormVisible: false,
    };
  }

  googleSignIn() {
    const provider = new GoogleAuthProvider();
    const auth = getAuth();
    signInWithPopup(auth, provider)
      .then((result) => {
        const credential = GoogleAuthProvider.credentialFromResult(result);
        this.setState({ user: credential.displayName });
      })
      .catch((error) => {
        this.setState({ error: error.message });
      });
  }

  handleSignIn() {
    this.setState({ signInFormVisible: true });
  }

  handleSignOut() {
    const auth = getAuth();
    signOut(auth).then(() => {
      this.setState({ user: null });
    });
  }

  render() {
    const { user, error, signInFormVisible } = this.state;
    return (
      <div>
        {user ? (
          <div>
            <Typography variant="h5">Logged in as {user} </Typography>
            <button onClick={this.handleSignOut.bind(this)}>Sign out</button>
          </div>
        ) : (
          <div>
            <button onClick={this.handleSignIn.bind(this)}>Sign in with Google</button>
          </div>
        )}
        {signInFormVisible && (
          <div>
            <form>
              <button onClick={this.googleSignIn.bind(this)}>Sign in with Google</button>
            </form>
          </div>
        )}
        {error && (
          <Snackbar
            message={error}
            autoHideDuration={6000}
            onClose={() => this.setState({ error: null })}
          />
        )}
      </div>
    );
  }
}
```
